"""OAuth 2.0 device-authorization flow against the Foxglove API, handing off to the browser for approval."""

from __future__ import annotations

import os
import time
import webbrowser

import httpx

from . import ui
from .api import http_error


class AuthError(RuntimeError):
    """Raised when the device flow cannot complete."""


def authenticate(
    api_url: str,
    client_id: str,
    *,
    open_browser: bool = True,
    signup: bool = True,
    app_url: str | None = None,
) -> str:
    """Run the device flow and return a session bearer token."""
    with httpx.Client(base_url=api_url, timeout=30.0) as client:
        code = _request_device_code(client, client_id, signup=signup)

        if app_url:
            verification_uri = f"{app_url.rstrip('/')}/activate?user_code={code['userCode']}"
        elif signup and code.get("signupVerificationUriComplete"):
            verification_uri = code["signupVerificationUriComplete"]
        else:
            verification_uri = code["verificationUriComplete"]

        ui.info("Approve this device in your browser to sign in.")
        ui.field("Verification code", code["userCode"])
        ui.info("Opening your browser. If it doesn't open, visit:")
        ui.link(verification_uri)
        if open_browser:
            _open_browser(verification_uri)

        id_token = _poll_for_token(client, client_id, code)
        return _signin(client, id_token)


def _open_browser(url: str) -> None:
    """Best-effort browser open"""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        saved_stderr = os.dup(2)
        try:
            os.dup2(devnull, 2)
            webbrowser.open(url)
        finally:
            os.dup2(saved_stderr, 2)
            os.close(saved_stderr)
            os.close(devnull)
    except Exception:  # opening a browser is best-effort
        pass


def _request_device_code(client: httpx.Client, client_id: str, *, signup: bool) -> dict:
    resp = client.post(
        "/v1/auth/device-code",
        json={"clientId": client_id, "signup": signup},
    )
    if resp.status_code != 200:
        raise AuthError(http_error(resp))
    return resp.json()


def _poll_for_token(client: httpx.Client, client_id: str, code: dict) -> str:
    interval = max(int(code.get("interval", 5)), 1)
    deadline = time.monotonic() + int(code.get("expiresIn", 900))

    print("Waiting for approval", end="", flush=True)
    while time.monotonic() < deadline:
        time.sleep(interval)
        print(".", end="", flush=True)
        resp = client.post(
            "/v1/auth/token",
            json={"deviceCode": code["deviceCode"], "clientId": client_id},
        )
        if resp.status_code == 200:
            print()
            return resp.json()["idToken"]
        if resp.status_code == 403:
            # The API returns 403 "Waiting for authorization" until the user approves.
            continue
        print()
        raise AuthError(http_error(resp))

    print()
    raise AuthError("timed out waiting for browser approval")


def _signin(client: httpx.Client, id_token: str) -> str:
    resp = client.post("/v1/signin", json={"idToken": id_token})
    if resp.status_code != 200:
        raise AuthError(http_error(resp))
    data = resp.json()
    token = data.get("bearerToken")
    if not token:
        raise AuthError(f"signin returned no bearerToken: {data}")
    return token
